```bash
#!/usr/bin/env bash
if [ "$1" == "--list" ]; then
cat<<EOF
{
  "bash_hosts": {
    "hosts": ["myhost.domain.com", "myhost2.domain.com"],
    "vars": {"host_test": "test-value"}
  },
  "_meta": {
    "hostvars": {
      "myhost.domain.com": {"host_specific_test_var": "test-value"}
    }
  }
}
EOF
elif [ "$1" == "--host" ]; then
  # not normally called because _meta is returned above
  echo '{"_meta": {"hostvars": {}}}'
else
  echo "Invalid option: use --list or --host <hostname>"
  exit 1
fi
